// VERIFICATION RUN. DRY_RUN true, so nothing is written. Re-derives fixes from
// live state after both write passes: any string that still needs a fix means a
// write did not land. Expected result: 0 remaining fixes.
const DRY_RUN = true;

const PROJECTS = [
  ['31393214664f295f94dd86.76792605', 'Personality.co',                     29251],
  ['7497898368b56f1d07ee46.54496723', 'MyImage - html/legal pages',          null],
  ['901014606819db6d0bc999.26230201', 'Mobitrace - html/legal pages',        null],
  ['18564477693fc9bba4cec8.54789459', 'My QR Code html',                     null],
  ['46919453689d5d729a1e70.59972091', 'PDF Editor - html/legal pages',       null],
  ['491848986923fad6dc2f85.42477363', 'QRcreate',                           25875],
  ['964775386a3ce03ecca883.03770715', 'Realchecker (FE)',                   29175],
  ['6744586768821f2c3fe845.13636914', 'PDF Editor (BE- emails)',            29306],
  ['3070657967b5854be32cb1.65162854', 'My Image',                           29359],
  ['9933660066825e9a8005c8.58526829', 'Personality - Members area content',  null],
  ['9274956467e3e224807498.79791832', 'Mobitrace - backend/emails',          null],
  ['60625870676151e1da46d0.81913446', 'My QR Code',                         25140],
  ['1286096867dbf31146afc5.54950617', 'PDF Editor',                        29360]
];

const qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor'
  + '&filter_translation_lang_ids=640,753';

return PROJECTS.map(function (p) {
  return { json: {
    dry_run: DRY_RUN,
    project_id: p[0], project_name: p[1], status_id: p[2],
    url: 'https://api.lokalise.com/api2/projects/' + p[0] + '/keys?' + qs
  } };
});

const cfgAll = $('Plan').all().map(function (x) { return x.json; });
const DRY = cfgAll[0].dry_run;
const META = {};
cfgAll.forEach(function (c) { META[c.project_id] = c; });

const errors = [];
const bodies = [];
for (const p of $input.all()) {
  const r = p.json || {};
  if (r.error !== undefined && r.body === undefined && r.keys === undefined) {
    errors.push({ kind: 'item_error', detail: String(JSON.stringify(r.error)).slice(0, 300) });
    continue;
  }
  const st = r.statusCode;
  const b = (r.body !== undefined) ? r.body : r;
  if (st !== undefined && st !== 200) {
    errors.push({ kind: 'http', status: st, body: JSON.stringify(b).slice(0, 300) });
    continue;
  }
  bodies.push(b);
}

const TH = '\u0E00-\u0E7F';
const THC = new RegExp('[' + TH + ']');
const QPART = ['หรือไม่','อย่างไร','เท่าใด','เท่าไร','ไหม','อะไร','ทำไม','เมื่อใด','ที่ไหน','ใคร','กี่'];
const LOAN = [['โพรไฟล์','โปรไฟล์','loan-profile'],['อีเมล์','อีเมล','loan-email'],
  ['อัพโหลด','อัปโหลด','loan-upload'],['ลิงค์','ลิงก์','loan-link'],
  ['เวปไซต์','เว็บไซต์','loan-website'],['คุ้กกี้','คุกกี้','loan-cookie'],
  ['โปรโมชั่น','โปรโมชัน','loan-promotion']];

function applyRules(th) {
  const fixes = [];
  let out = th;
  if (out.indexOf('\u00a0') >= 0) { out = out.split('\u00a0').join(' '); fixes.push('ws-nbsp'); }
  if (out.indexOf('\u200b') >= 0) { out = out.split('\u200b').join(''); fixes.push('ws-zwsp'); }
  if (out.indexOf('\u2011') >= 0) { out = out.split('\u2011').join('-'); fixes.push('ws-nbhyphen'); }
  for (const L of LOAN) {
    if (out.indexOf(L[0]) >= 0) { out = out.split(L[0]).join(L[1]); fixes.push(L[2]); }
  }
  let n = out.replace(/QR\s*โค้ด/g, 'คิวอาร์โค้ด').replace(/รหัส\s*QR/g, 'คิวอาร์โค้ด');
  if (n !== out) { out = n; fixes.push('term-qrcode'); }
  if (/[\u0E50-\u0E59]/.test(out)) {
    out = out.replace(/[\u0E50-\u0E59]/g, function (c) { return String(c.charCodeAt(0) - 0x0E50); });
    fixes.push('num-thaidigits');
  }
  if (/[\u201c\u201d]/.test(out)) { out = out.replace(/[\u201c\u201d]/g, '"'); fixes.push('punct-quotes'); }
  if (out.indexOf('\u2026') >= 0) { out = out.split('\u2026').join('...'); fixes.push('punct-ellipsis'); }
  if (out.indexOf('กรุณา') >= 0) { out = out.split('กรุณา').join('โปรด'); fixes.push('tone-please'); }
  const thanRe = new RegExp('(?<![' + TH + '])ท่าน', 'g');
  if (thanRe.test(out) && out.indexOf('ผู้ท่าน') < 0) {
    out = out.replace(new RegExp('(?<![' + TH + '])ท่าน', 'g'), 'คุณ');
    fixes.push('tone-2ndperson');
  }
  n = out.replace(new RegExp('([' + TH + '])([A-Za-z0-9])', 'g'), '$1 $2')
         .replace(new RegExp('([A-Za-z0-9])([' + TH + '])', 'g'), '$1 $2');
  if (n !== out) { out = n; fixes.push('space-script'); }
  n = out.replace(new RegExp('ๆ(?=[' + TH + '])', 'g'), 'ๆ ');
  if (n !== out) { out = n; fixes.push('space-yamok'); }
  n = out.replace(/\sๆ/g, 'ๆ');
  if (n !== out) { out = n; fixes.push('space-yamok-before'); }
  n = out.replace(/ {2,}/g, ' ').trim();
  if (n !== out) { out = n; fixes.push('ws-collapse'); }
  if (/[^.]\.$/.test(out) && THC.test(out)) {
    out = out.replace(/\.$/, '').replace(/\s+$/, '');
    fixes.push('punct-nofinalstop');
  }
  if (out.charAt(out.length - 1) === '?') {
    let hasQ = false;
    for (const q of QPART) { if (out.indexOf(q) >= 0) { hasQ = true; break; } }
    if (hasQ) {
      out = out.replace(/\?+$/, '').replace(/\s+$/, '');
      fixes.push('punct-noquestionmark');
    } else {
      fixes.push('FLAG-question-no-particle');
    }
  }
  return { out: out, fixes: fixes };
}

const MTACC = { 'support@lokali.se': 1, 'support@lokalise.co': 1 };
const groups = {};
const histogram = {};
let scanned = 0, candidates = 0, changed = 0, flagged = 0;

for (const b of bodies) {
  const pid = String(b.project_id || '');
  const meta = META[pid] || {};
  if (!groups[pid]) groups[pid] = { project_id: pid, project: meta.project_name || pid,
    status_id: meta.status_id, keys: [] };
  for (const k of (b.keys || [])) {
    if (k.is_archived === true) continue;
    if (k.is_plural === true) continue;   // JSON blobs, excluded from text rules
    let tgt = null;
    for (const t of (k.translations || [])) { if (t.language_iso === 'th') tgt = t; }
    if (!tgt) continue;
    const v = tgt.translation;
    const txt = (typeof v === 'string') ? v : JSON.stringify(v);
    if (!txt || !String(txt).trim()) continue;
    scanned++;
    if (tgt.is_reviewed) continue;
    const who = tgt.modified_by_email || '';
    const stats = (tgt.custom_translation_statuses || []).map(function (x) { return x.title; });
    const sigStatus = stats.indexOf('MT_to_review') >= 0;
    const sigBot = !!MTACC[who] || tgt.modified_by === 1 || tgt.modified_by === 2;
    const sigUnv = !!tgt.is_unverified || !!tgt.is_fuzzy;
    if (!(sigStatus || sigBot || sigUnv)) continue;
    candidates++;

    const res = applyRules(txt);
    const real = res.fixes.filter(function (f) { return f.indexOf('FLAG') !== 0; });
    for (const f of res.fixes) { histogram[f] = (histogram[f] || 0) + 1; }
    if (res.fixes.some(function (f) { return f.indexOf('FLAG') === 0; })) flagged++;
    if (real.length === 0 || res.out === txt) continue;
    changed++;

    groups[pid].keys.push({ key_id: k.key_id, translation_id: tgt.translation_id,
      key: (k.key_name || {}).web || (k.key_name || {}).other || '',
      old: txt, neu: res.out, rules: real.join('|') });
  }
}

const out = [];
for (const pid of Object.keys(groups)) {
  const g = groups[pid];
  if (!g.keys.length) continue;
  out.push({ json: {
    dry_run: DRY,
    project_id: pid, project: g.project, status_id: g.status_id,
    fix_count: g.keys.length,
    snapshot: g.keys.map(function (x) { return { key_id: x.key_id, translation_id: x.translation_id,
      key: x.key, original: x.old, intended: x.neu, rules: x.rules }; }),
    payload: { keys: g.keys.map(function (x) {
      const tr = { language_iso: 'th', translation: x.neu };
      if (g.status_id) { tr.custom_translation_status_ids = [g.status_id]; }
      return { key_id: x.key_id, translations: [tr] };
    }) },
    put_url: 'https://api.lokalise.com/api2/projects/' + pid + '/keys',
    summary: { scanned: scanned, candidates: candidates, changed: changed,
      flagged: flagged, histogram: histogram, fetch_errors: errors,
      projects_with_fixes: Object.keys(groups).filter(function (p) { return groups[p].keys.length; }).length }
  } });
}

return out;

// PUT /keys returns 200 with a per-key errors array, exactly like the glossary
// endpoint. The status code alone is not evidence of success, so the array is
// read explicitly and every project is accounted for.
const derived = $('Derive fixes').all().map(function (x) { return x.json; });
const items = $input.all();

const perProject = [];
let attempted = 0, updated = 0, apiErrors = 0;

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const src = derived[i] || {};
  const body = (r.body !== undefined) ? r.body : r;
  const errs = (body && body.errors) || [];
  const keys = (body && body.keys) || [];

  attempted += src.fix_count || 0;
  updated += keys.length;
  apiErrors += errs.length;

  perProject.push({
    project: src.project,
    project_id: src.project_id,
    status_id: src.status_id,
    status_applied: src.status_id ? 'yes' : 'no - custom statuses disabled in this project',
    fixes_sent: src.fix_count || 0,
    http_status: r.statusCode,
    keys_returned: keys.length,
    api_error_count: errs.length,
    api_errors: errs.slice(0, 5)
  });
}

const clean = apiErrors === 0 && perProject.every(function (p) { return p.http_status === 200; });

return [{ json: {
  verdict: clean
    ? 'Writes accepted with no API errors - confirm with an independent re-read'
    : 'API ERRORS PRESENT - inspect per_project before trusting anything',
  projects: perProject.length,
  fixes_attempted: attempted,
  keys_returned_total: updated,
  api_error_total: apiErrors,
  strings_with_status: perProject.filter(function (p) { return p.status_id; })
    .reduce(function (a, p) { return a + p.fixes_sent; }, 0),
  strings_without_status: perProject.filter(function (p) { return !p.status_id; })
    .reduce(function (a, p) { return a + p.fixes_sent; }, 0),
  per_project: perProject } }];
